"""Signature that marks a PDF as generated by this server's demo-scenario generator (app/seed/docgen.py).

The demo files in ``test scenario data/`` can be uploaded by hand, without the one-click demo token. When every
uploaded document is a PDF carrying this signature for the claim's bill number, the claim is treated as a demo
claim: stored and shown like any other but kept out of the history later claims are compared with
(``app/db/repos.py`` DEMO_CHANNEL), so a scenario gives the same result however often it is submitted.

The signature is an HMAC of the bill number with the server's JWT secret, so only this server (or a script run
with the same .env) can produce it. Demo marking is for test environments; disable the demo routes in production.
"""
from __future__ import annotations

import hashlib
import hmac
import io

META_KEY = "/ClaimShieldDemo"


def _key() -> bytes | None:
    from app.settings import get_settings

    secret = get_settings().jwt_secret
    value = secret.get_secret_value().strip() if secret else ""
    return value.encode() if value else None


def signature(invoice_number: str) -> str | None:
    key = _key()
    if key is None:
        return None
    return hmac.new(key, f"claimshield-demo:{invoice_number.strip()}".encode(), hashlib.sha256).hexdigest()[:32]


def is_signed_demo(docs, invoice_number: str) -> bool:
    """True when there is at least one document and every one is a PDF signed for ``invoice_number``."""
    expected = signature(invoice_number or "")
    if not expected or not docs:
        return False
    from pypdf import PdfReader

    for d in docs:
        if d.content_type != "application/pdf":
            return False
        try:
            meta = PdfReader(io.BytesIO(d.data)).metadata or {}
        except Exception:
            return False
        if not hmac.compare_digest(str(meta.get(META_KEY, "")), expected):
            return False
    return True
